"""Owner-only real-race manual 3連単 formation notebook.

No licensed records or prediction engine. JS only stores manual drafts in
same-origin localStorage; WSGI only serves fixed source text after authentication.
"""
HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>競馬ナイン｜自分の3連単下書き</title><link rel=\"stylesheet\" href=\"/my-tickets.css\"></head><body><main><header><a href=\"/\" class=\"back\">← 競馬ナインに戻る</a><h1>自分の3連単下書き</h1><p class=\"muted\">実際の開催日を選べる、本人用の手動フォーメーション作成帳。</p><p class=\"warning\">これは本人が選んだ買い目の下書きです。AI予想・JRAの出走確定・購入履歴ではありません。</p></header><section><h2>開催日・レースを選択</h2><label for=\"mDate\">日付</label><input id=\"mDate\" type=\"date\"><div class=\"two\"><div><label for=\"mTrack\">競馬場</label><select id=\"mTrack\"><option value=\"\">競馬場を選択</option><option value=\"札幌\">札幌</option><option value=\"函館\">函館</option><option value=\"福島\">福島</option><option value=\"新潟\">新潟</option><option value=\"東京\">東京</option><option value=\"中山\">中山</option><option value=\"中京\">中京</option><option value=\"京都\">京都</option><option value=\"阪神\">阪神</option><option value=\"小倉\">小倉</option></select></div><div><label for=\"mRace\">レース</label><select id=\"mRace\"><option value=\"1\">1R</option><option value=\"2\">2R</option><option value=\"3\">3R</option><option value=\"4\">4R</option><option value=\"5\">5R</option><option value=\"6\">6R</option><option value=\"7\">7R</option><option value=\"8\">8R</option><option value=\"9\">9R</option><option value=\"10\">10R</option><option value=\"11\">11R</option><option value=\"12\">12R</option></select></div></div><div class=\"race-nav\"><button id=\"mPrevRace\" type=\"button\" class=\"secondary\">← 前のR</button><button id=\"mNextRace\" type=\"button\" class=\"secondary\">次のR →</button></div></section><section><h2>3連単フォーメーション</h2><p class=\"muted\">1着・2着・3着に入れる馬番をタップ。各着順は複数選択OK。重複を除いて最大48点。</p><h3>1着候補</h3><div id=\"mFirst\" class=\"numbers\" aria-label=\"1着候補\"></div><h3>2着候補</h3><div id=\"mSecond\" class=\"numbers\" aria-label=\"2着候補\"></div><h3>3着候補</h3><div id=\"mThird\" class=\"numbers\" aria-label=\"3着候補\"></div><p class=\"muted\">作り方：通常は着順別に馬番を選択。軸流しは、選んだ候補から3着や2着を自動でセットします（保存前に全買い目を確認）。</p><div class=\"quick-actions\"><button id=\"mAxisSingle\" type=\"button\" class=\"secondary\">1頭軸ながし（1着固定）</button><button id=\"mAxisPair\" type=\"button\" class=\"secondary\">2頭軸ながし（1・2着）</button><button id=\"mCopyThird\" type=\"button\" class=\"secondary\">2着候補を3着にもコピー</button></div><div class=\"total\"><div>買い目<strong id=\"mCount\">0点</strong></div><div>1点100円<strong id=\"mCost\">0円</strong></div></div><p id=\"mMsg\" role=\"status\" class=\"muted\">各着順の馬番を選択してください。</p><button id=\"mSave\" disabled>このレースの下書きを保存</button><button id=\"mReset\" class=\"secondary\">選択をクリア</button><details><summary>作成した全買い目を見る</summary><ol id=\"mTickets\"></ol></details></section><section><h2>選択した日付の保存済み下書き</h2><p class=\"muted\">他の日付の買い目はこの画面には表示しません。日付を変えると、その日の下書きを確認できます。</p><div id=\"mSaved\" role=\"region\" aria-label=\"保存済み下書き\"></div><label for=\"mImport\">JSONバックアップから下書きを復元</label><input id=\"mImport\" type=\"file\" accept=\".json,application/json\"><p class=\"muted\">事前に現在の下書きを書き出してください。復元時は内容確認後、現在の下書き全件と入れ替えます。ファイルはサーバーへ送信されません。</p><button id=\"mExport\" class=\"secondary\">下書きをJSONでバックアップ</button><p class=\"muted\">このブラウザの端末内だけに保存（Google同期なし）。プライベートブラウズ・ChatGPT内ブラウザ・Safariは保存領域が異なる場合があります。端末変更やサイトデータ削除に備え、Safariからバックアップしてください。</p></section></main><script src=\"/my-tickets.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#f1f6ff;font:16px/1.55 system-ui,sans-serif}main{max-width:640px;margin:auto;padding:18px 14px 40px}a{color:#edca70}h1{font-size:26px;margin:10px 0}h2{font-size:20px;margin:0 0 10px}h3{font-size:16px;margin:17px 0 7px}.back{font-size:14px}section{background:#172d48;border:1px solid #385471;border-radius:16px;padding:18px;margin:16px 0}.muted{font-size:13px;color:#c8d7e6}.warning{background:#312b23;border:1px solid #a8884c;border-radius:12px;padding:12px;color:#ffe2a0;font-size:13px}label{display:block;margin:8px 0 5px;font-weight:700}input,select{width:100%;border:1px solid #7992aa;border-radius:10px;background:#0d243c;color:#fff;min-height:48px;padding:10px;font:inherit}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.race-nav,.quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0 6px}.race-nav button,.quick-actions button{margin:0;min-height:46px;font-size:14px}.quick-actions button:last-child{grid-column:1/-1}.quick-actions button:disabled{opacity:.36}.numbers{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px}.num{border:1px solid #617996;background:#0a2239;color:#fff;border-radius:8px;min-height:48px;padding:0;font:700 18px system-ui}.num.selected{background:#d4af37;border-color:#f3d17a;color:#10213b}.total{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:22px}.total>div{background:#0c2239;padding:12px 8px;border-radius:11px;text-align:center;font-size:12px;color:#cfdded}.total strong{display:block;font-size:26px;color:#fff;font-variant-numeric:tabular-nums}button{font:700 16px system-ui;min-height:49px;padding:10px 15px;border:0;border-radius:10px;background:#edca70;color:#11243b;margin:8px 0;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button.secondary{background:#304d6e;color:#fff}#mSave{width:100%}#mReset,#mExport{width:100%}details{border:1px solid #4d6581;border-radius:10px;padding:12px;margin-top:14px}details summary{cursor:pointer}ol{columns:2;font-size:14px;line-height:1.9}.saved{padding:13px 0;border-bottom:1px solid #3d5874}.saved strong{display:block}.saved .secondary{min-height:40px;margin-right:8px}p{overflow-wrap:anywhere}@media(max-width:360px){.numbers{gap:5px}.num{min-height:44px;font-size:16px}section{padding:13px}}"
JS = "'use strict';\n// Private, browser-only operator draft. No licensed data, official prediction,\n// purchased-ticket claim, provider API call or server-side persistence.\nconst $=id=>document.getElementById(id);\nconst KEY='keiba-nine-owner-ticket-drafts-v1', LIMIT=48, MAX_SAVED=300;\nconst TRACKS=[\"札幌\",\"函館\",\"福島\",\"新潟\",\"東京\",\"中山\",\"中京\",\"京都\",\"阪神\",\"小倉\"];\nconst sorted=s=>[...s].sort((a,b)=>a-b);\nfunction ticketsFor(first,second,third){\n const tickets=[],unique=new Set();\n for(const a of sorted(first))for(const b of sorted(second))for(const c of sorted(third)){\n  if(a===b||a===c||b===c)continue;\n  const key=a+'-'+b+'-'+c;\n  if(!unique.has(key)){unique.add(key);tickets.push(key);}\n }\n return tickets;\n}\nfunction validDate(x){\n if(typeof x!=='string'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(x))return false;\n const n=new Date(x+'T12:00:00Z');\n return Number.isFinite(n.valueOf())&&n.toISOString().slice(0,10)===x;\n}\nfunction validNums(a){return Array.isArray(a)&&a.length<=18&&\n a.every(x=>Number.isInteger(x)&&x>=1&&x<=18)&&new Set(a).size===a.length;}\nfunction validRecord(r){\n return r&&typeof r==='object'&&validDate(r.date)&&TRACKS.includes(r.track)&&\n Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n validNums(r.first)&&validNums(r.second)&&validNums(r.third)&&\n typeof r.savedAt==='string'&&r.savedAt.length<=32&&\n ticketsFor(r.first,r.second,r.third).length>=1&&\n ticketsFor(r.first,r.second,r.third).length<=LIMIT;\n}\nlet records=[];\ntry{\n const raw=JSON.parse(localStorage.getItem(KEY)||'[]');\n if(Array.isArray(raw))records=raw.slice(-MAX_SAVED).filter(validRecord).map(r=>({\n  date:r.date,track:r.track,race:r.race,first:r.first,second:r.second,\n  third:r.third,savedAt:r.savedAt\n }));\n}catch(_){}\nlet first=new Set(),second=new Set(),third=new Set();\nconst groups=[['mFirst',()=>first],['mSecond',()=>second],['mThird',()=>third]];\nfunction keyOf(date,track,race){return date+'|'+track+'|'+race;}\nfunction currentKey(){return keyOf($('mDate').value,$('mTrack').value,Number($('mRace').value));}\nfunction toYen(x){return x.toLocaleString('ja-JP')+'円';}\nfunction message(x){$('mMsg').textContent=x;}\nfunction readForm(){\n const date=$('mDate').value,track=$('mTrack').value,race=Number($('mRace').value);\n if(!validDate(date)||!TRACKS.includes(track)||!Number.isInteger(race)||race<1||race>12)\n  return null;\n return {date,track,race};\n}\nfunction render(){\n const combos=ticketsFor(first,second,third),points=combos.length;\n $('mCount').textContent=points+'点';\n $('mCost').textContent=toYen(points*100);\n $('mSave').disabled=!readForm()||points<1||points>LIMIT;\n const list=$('mTickets');list.replaceChildren();\n if(points<=LIMIT){for(const ticket of combos){\n  const li=document.createElement('li');li.textContent=ticket;list.append(li);\n }}\n for(const [id,getSet] of groups){const active=getSet();\n  for(const node of $(id).children){\n   const selected=active.has(Number(node.dataset.number));\n   node.className=selected?'num selected':'num';\n   node.setAttribute('aria-pressed',String(selected));\n  }\n }\n const race=Number($('mRace').value);\n $('mPrevRace').disabled=race<=1;\n $('mNextRace').disabled=race>=12;\n if(points>LIMIT)message(points+'点は48点を超えています。候補を減らしてください。');\n else if(points===0)message('各着順の馬番を選択してください。');\n else message(points+'点・'+toYen(points*100)+'。買い目は未購入の下書きです。');\n}\nfunction applyQuick(mode){\n let newFirst=new Set(first),newSecond=new Set(second),newThird=new Set(third),label='';\n if(mode==='single'){\n  if(first.size!==1){message('1着候補を1頭だけ選んでください。');return;}\n  const opponents=new Set([...second].filter(n=>!first.has(n)));\n  if(opponents.size<2){message('2着候補に相手を2頭以上選んでください。');return;}\n  newSecond=opponents;newThird=new Set(opponents);\n  label='1頭軸ながし';\n }else if(mode==='pair'){\n  if(first.size!==2){message('1着候補に軸の2頭を選んでください。');return;}\n  const opponents=new Set([...third].filter(n=>!first.has(n)));\n  if(!opponents.size){message('3着候補に軸以外の相手を選んでください。');return;}\n  newSecond=new Set(first);newThird=opponents;\n  label='2頭軸ながし（1・2着を入替）';\n }else if(mode==='copy'){\n  if(!second.size){message('先に2着候補を選んでください。');return;}\n  newThird=new Set(second);\n  label='2着候補を3着へコピー';\n }else return;\n const count=ticketsFor(newFirst,newSecond,newThird).length;\n if(!count||count>LIMIT){\n  message(count?count+'点は48点を超えるため反映しません。相手候補を減らしてください。':'有効な買い目がありません。軸と相手は違う馬番を選んでください。');\n  return;\n }\n first=newFirst;second=newSecond;third=newThird;\n render();\n message(label+'を反映：'+count+'点・'+toYen(count*100)+'。保存前に買い目を確認してください。');\n}\nfunction changeRace(delta){\n const next=Number($('mRace').value)+delta;\n if(next<1||next>12)return;\n $('mRace').value=String(next);\n loadSelected();showDay();\n}\nfunction showDay(){\n const host=$('mSaved');host.replaceChildren();\n const date=$('mDate').value;\n const rows=records.filter(r=>r.date===date).slice().sort((a,b)=>a.track.localeCompare(b.track,'ja')||a.race-b.race);\n if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='この日付に保存した下書きはありません。';host.append(p);return;}\n for(const r of rows){\n  const div=document.createElement('div');div.className='saved';\n  const title=document.createElement('strong');title.textContent=r.track+r.race+'R｜'+ticketsFor(r.first,r.second,r.third).length+'点';\n  const note=document.createElement('p');note.className='muted';\n  note.textContent='1着 '+r.first.join('・')+'／2着 '+r.second.join('・')+'／3着 '+r.third.join('・')+'｜未購入の下書き';\n  const edit=document.createElement('button');edit.className='secondary';edit.textContent='編集';\n  edit.onclick=()=>{$('mTrack').value=r.track;$('mRace').value=String(r.race);loadSelected();};\n  const del=document.createElement('button');del.className='secondary';del.textContent='削除';\n  del.onclick=()=>{\n   if(!confirm(r.track+r.race+'Rの下書きを削除しますか？'))return;\n   const old=records.slice();records=records.filter(x=>keyOf(x.date,x.track,x.race)!==keyOf(r.date,r.track,r.race));\n   if(!persist()){records=old;message('削除を保存できませんでした。');return;}\n   if(currentKey()===keyOf(r.date,r.track,r.race))loadSelected();\n   showDay();message('下書きを削除しました。');\n  };\n  div.append(title,note,edit,del);host.append(div);\n }\n}\nfunction loadSelected(){\n const r=records.find(x=>keyOf(x.date,x.track,x.race)===currentKey());\n first=new Set(r?r.first:[]);second=new Set(r?r.second:[]);third=new Set(r?r.third:[]);\n render();\n}\nfunction persist(){\n try{localStorage.setItem(KEY,JSON.stringify(records));return true;}\n catch(_){return false;}\n}\nfor(const [id,getSet] of groups){\n const host=$(id);\n for(let n=1;n<=18;n++){\n  const btn=document.createElement('button');btn.type='button';btn.className='num';\n  btn.textContent=String(n);btn.dataset.number=String(n);\n  btn.setAttribute('aria-pressed','false');\n  btn.onclick=()=>{const set=getSet();if(set.has(n))set.delete(n);else set.add(n);render();};\n  host.append(btn);\n }\n}\n$('mAxisSingle').onclick=()=>applyQuick('single');\n$('mAxisPair').onclick=()=>applyQuick('pair');\n$('mCopyThird').onclick=()=>applyQuick('copy');\n$('mPrevRace').onclick=()=>changeRace(-1);\n$('mNextRace').onclick=()=>changeRace(1);\n$('mDate').value=new Date(Date.now()+9*60*60*1000).toISOString().slice(0,10);\n$('mDate').onchange=()=>{loadSelected();showDay();};\n$('mImport').onchange=async()=>{\n const picker=$('mImport'),file=picker.files&&picker.files[0];\n if(!file)return;\n try{\n  if(!Number.isSafeInteger(file.size)||file.size<1||file.size>1024*1024)\n   throw new Error('ファイルサイズが不正です（上限1MB）。');\n  const data=JSON.parse(await file.text()),raw=data&&data.records;\n  if(!data||data.format!=='keiba-nine-owner-drafts-1'||\n     !Array.isArray(raw)||raw.length<1||raw.length>MAX_SAVED||\n     !raw.every(validRecord))\n   throw new Error('下書きのバックアップ形式か内容が正しくありません。');\n  const keys=new Set(raw.map(r=>keyOf(r.date,r.track,r.race)));\n  if(keys.size!==raw.length)\n   throw new Error('同じ日付・レースが重複しているため復元できません。');\n  const restored=raw.map(r=>({date:r.date,track:r.track,race:r.race,\n   first:r.first.slice(),second:r.second.slice(),third:r.third.slice(),savedAt:r.savedAt}));\n  if(!confirm('現在の下書き '+records.length+'件を、バックアップ '+restored.length+\n    '件で全件置き換えます。事前に現在のJSONを保存しましたか？'))return;\n  const previous=records;\n  records=restored;\n  if(!persist()){\n   records=previous;message('端末へ保存できず、元の下書きはそのままです。');return;\n  }\n  loadSelected();showDay();\n  message('下書き '+restored.length+'件を復元しました。これは購入記録ではありません。');\n }catch(err){message('復元できません：'+(err instanceof Error?err.message:'ファイルを確認してください。'));}\n finally{picker.value='';}\n};\n$('mTrack').onchange=loadSelected;\n$('mRace').onchange=loadSelected;\n$('mReset').onclick=()=>{first.clear();second.clear();third.clear();render();};\n$('mSave').onclick=()=>{\n const choice=readForm(),combos=ticketsFor(first,second,third);\n if(!choice||combos.length<1||combos.length>LIMIT){message('日付・競馬場・点数を確認してください。');return;}\n const i=records.findIndex(x=>keyOf(x.date,x.track,x.race)===currentKey());\n if(i>=0&&!confirm('このレースの下書きを上書きしますか？'))return;\n if(i<0&&records.length>=MAX_SAVED){message('保存上限です。古い下書きを削除してください。');return;}\n const old=records.slice(),r={...choice,first:sorted(first),second:sorted(second),third:sorted(third),\n  savedAt:new Date().toISOString()};\n if(i>=0)records[i]=r;else records.push(r);\n if(!persist()){records=old;message('保存できません。Safariのストレージを確認してください。');return;}\n showDay();message('下書きを保存しました。端末内保存のみ・購入記録ではありません。');\n};\n$('mExport').onclick=()=>{\n if(!records.length){message('保存された下書きがありません。');return;}\n try{\n  const data={format:'keiba-nine-owner-drafts-1',exportedAt:new Date().toISOString(),records};\n  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});\n  const url=URL.createObjectURL(blob),a=document.createElement('a');\n  a.href=url;a.download='keiba-nine-manual-drafts.json';a.click();\n  URL.revokeObjectURL(url);message('バックアップを書き出しました。ファイルの保存先を確認してください。');\n }catch(_){message('このブラウザでは書き出せません。Safariでお試しください。');}\n};\nloadSelected();showDay();"
